// Regenerate public/js/rules.js from ../interpret/rules.yaml (pure data; expressions are parsed by
// public/js/expr.js — a tiny safe evaluator, no eval/Function in the client).
const y = require('js-yaml'), fs = require('fs'), path = require('path');
const r = y.load(fs.readFileSync(path.join(__dirname, '../../interpret/rules.yaml'), 'utf8'));
fs.writeFileSync(path.join(__dirname, '../public/js/rules.js'),
  '// auto-generated by tools/gen_rules.cjs from interpret/rules.yaml — do not hand-edit\n' +
  'export const RULES = ' + JSON.stringify(r, null, 1) + ';\n');
console.log('ok', Object.keys(r.lucks), r.types.length, 'types');
